<?php
declare(strict_types=1);

if (PHP_SAPI !== 'cli') {
    http_response_code(403);
    exit("Запустите через PHP CLI.\n");
}

const LK3_VERSION = '2026.08.02.17';
const LK3_JS_MARKER = 'LK3_PROJECT_SOURCES_BUNDLED_V180217';
const LK3_REPOSITORY_MARKER = 'LK3_SELECTED_PROJECT_V180217';

function lk3out(string $message = ''): void
{
    fwrite(STDOUT, $message . PHP_EOL);
}

function lk3read(string $path): string
{
    $content = file_get_contents($path);
    if (!is_string($content)) {
        throw new RuntimeException('Не удалось прочитать файл: ' . $path);
    }
    return $content;
}

function lk3write(string $path, string $content): void
{
    $directory = dirname($path);
    if (!is_dir($directory) && !mkdir($directory, 0775, true) && !is_dir($directory)) {
        throw new RuntimeException('Не удалось создать каталог: ' . $directory);
    }
    $temporary = $path . '.tmp.' . bin2hex(random_bytes(5));
    if (file_put_contents($temporary, $content, LOCK_EX) === false) {
        throw new RuntimeException('Не удалось записать файл: ' . $temporary);
    }
    if (!rename($temporary, $path)) {
        @unlink($temporary);
        throw new RuntimeException('Не удалось заменить файл: ' . $path);
    }
}

function lk3lint(string $path): void
{
    if (!function_exists('exec')) {
        return;
    }
    $output = [];
    $code = 0;
    exec(
        escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg($path) . ' 2>&1',
        $output,
        $code
    );
    if ($code !== 0) {
        throw new RuntimeException(
            'Ошибка PHP-синтаксиса в ' . $path . ':\n' . implode("\n", $output)
        );
    }
}

function lk3tableExists(PDO $pdo, string $table): bool
{
    $stmt = $pdo->prepare(
        'SELECT COUNT(*) FROM information_schema.TABLES '
        . 'WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :table_name'
    );
    $stmt->execute(['table_name' => $table]);
    return (int) $stmt->fetchColumn() > 0;
}

function lk3columnExists(PDO $pdo, string $table, string $column): bool
{
    $stmt = $pdo->prepare(
        'SELECT COUNT(*) FROM information_schema.COLUMNS '
        . 'WHERE TABLE_SCHEMA = DATABASE() '
        . 'AND TABLE_NAME = :table_name AND COLUMN_NAME = :column_name'
    );
    $stmt->execute([
        'table_name' => $table,
        'column_name' => $column,
    ]);
    return (int) $stmt->fetchColumn() > 0;
}

function lk3addColumn(
    PDO $pdo,
    string $table,
    string $column,
    string $definition,
    array &$addedColumns
): void {
    if (!lk3tableExists($pdo, $table) || lk3columnExists($pdo, $table, $column)) {
        return;
    }
    $safeTable = str_replace('`', '', $table);
    $safeColumn = str_replace('`', '', $column);
    $pdo->exec(
        'ALTER TABLE `' . $safeTable . '` ADD COLUMN `'
        . $safeColumn . '` ' . $definition
    );
    $addedColumns[] = [$safeTable, $safeColumn];
}

function lk3decodePayload(): array
{
    $encoded = <<<'PAYLOAD'

PAYLOAD;
    $json = base64_decode(preg_replace('/\s+/', '', $encoded) ?? '', true);
    if (!is_string($json) || $json === '') {
        throw new RuntimeException('Не удалось декодировать пакет LK.3.');
    }
    if (!hash_equals('2b6f0d3dee8a7b6612e5c8c206d15a7466646887f08143653ef3f355e4e91196', hash('sha256', $json))) {
        throw new RuntimeException('Не совпала SHA-256 пакета LK.3.');
    }
    $payload = json_decode($json, true);
    if (!is_array($payload)) {
        throw new RuntimeException('Некорректный пакет LK.3.');
    }
    $result = [];
    foreach ($payload as $key => $item) {
        if (!is_array($item)) {
            throw new RuntimeException('Некорректный компонент LK.3: ' . $key);
        }
        $content = base64_decode((string) ($item['content'] ?? ''), true);
        if (!is_string($content)) {
            throw new RuntimeException('Не удалось декодировать компонент LK.3: ' . $key);
        }
        if (!hash_equals((string) ($item['sha256'] ?? ''), hash('sha256', $content))) {
            throw new RuntimeException('Не совпала SHA-256 компонента LK.3: ' . $key);
        }
        $result[(string) $key] = $content;
    }
    return $result;
}

function lk3injectFirstActive(string $content): string
{
    if (str_contains($content, LK3_REPOSITORY_MARKER)) {
        return $content;
    }

    $injection = <<<'PHPBLOCK'

        /* LK3_SELECTED_PROJECT_V180217 */
        try {
            if (class_exists(\SeoAnalytics\Services\ProjectSourceService::class)) {
                $lk3SelectedProject = (new \SeoAnalytics\Services\ProjectSourceService())
                    ->selectedLegacyProject();
                if ((int) ($lk3SelectedProject['id'] ?? 0) > 0) {
                    return $lk3SelectedProject;
                }
            }
        } catch (\Throwable) {
            // Фоновые и системные процессы без пользовательской сессии
            // продолжают использовать исходный первый активный проект.
        }
PHPBLOCK;

    $tokens = token_get_all($content);
    $result = '';
    $afterFunction = false;
    $target = false;
    $inserted = 0;

    foreach ($tokens as $token) {
        $id = is_array($token) ? $token[0] : null;
        $text = is_array($token) ? $token[1] : $token;

        if ($id === T_FUNCTION) {
            $afterFunction = true;
            $target = false;
        } elseif ($afterFunction && $id === T_STRING) {
            $target = $text === 'firstActive';
            $afterFunction = false;
        } elseif ($afterFunction && is_string($text) && trim($text) !== '' && $text !== '&') {
            $afterFunction = false;
        }

        $result .= $text;

        if ($target && $text === '{') {
            $result .= $injection;
            $target = false;
            $inserted++;
        }
    }

    if ($inserted !== 1) {
        throw new RuntimeException(
            'Не удалось безопасно изменить ProjectRepository::firstActive(); вставок: '
            . $inserted
        );
    }
    return $result;
}
$root = getcwd() ?: '';
$required = [
    $root . '/app/bootstrap.php',
    $root . '/app/Services/PortalAccessService.php',
    $root . '/app/Services/PortalContextService.php',
    $root . '/app/Repositories/ProjectRepository.php',
    $root . '/assets/app.js',
    $root . '/assets/app.css',
    $root . '/sql/schema.sql',
];
foreach ($required as $path) {
    if (!is_file($path)) {
        throw new RuntimeException('Не найден обязательный файл LK.3: ' . $path);
    }
}

$appJsPath = $root . '/assets/app.js';
$appCssPath = $root . '/assets/app.css';
$schemaPath = $root . '/sql/schema.sql';
$repositoryPath = $root . '/app/Repositories/ProjectRepository.php';
$servicePath = $root . '/app/Services/ProjectSourceService.php';
$apiPath = $root . '/project-sources-api.php';

if (!str_contains(lk3read($appJsPath), 'LK2_CLIENT_STRUCTURE_BUNDLED_V180216')) {
    throw new RuntimeException(
        'Версия ' . LK3_VERSION . ' требует установленный LK.2 / 2026.08.02.16.'
    );
}

$payload = lk3decodePayload();
$tracked = [
    'app/Repositories/ProjectRepository.php',
    'app/Services/ProjectSourceService.php',
    'project-sources-api.php',
    'assets/app.js',
    'assets/app.css',
    'sql/schema.sql',
];
$backupDirectory = $root . '/storage/backups/lk3-project-sources-'
    . date('Ymd-His') . '-' . bin2hex(random_bytes(3));
if (!mkdir($backupDirectory, 0700, true) && !is_dir($backupDirectory)) {
    throw new RuntimeException('Не удалось создать резервную копию LK.3.');
}

$manifest = [];
foreach ($tracked as $relative) {
    $source = $root . '/' . $relative;
    $manifest[$relative] = is_file($source);
    if (!is_file($source)) {
        continue;
    }
    $destination = $backupDirectory . '/' . $relative;
    $directory = dirname($destination);
    if (!is_dir($directory) && !mkdir($directory, 0700, true) && !is_dir($directory)) {
        throw new RuntimeException('Не удалось создать каталог копии LK.3.');
    }
    if (!copy($source, $destination)) {
        throw new RuntimeException('Не удалось сохранить копию LK.3: ' . $relative);
    }
}

require_once $root . '/app/bootstrap.php';
$pdo = \SeoAnalytics\Core\Database::pdo();
$tableState = [
    'project_source_links' => lk3tableExists($pdo, 'project_source_links'),
    'report_site_links' => lk3tableExists($pdo, 'report_site_links'),
];
$addedColumns = [];

try {
    lk3write($servicePath, (string) ($payload['service'] ?? ''));
    lk3write($apiPath, (string) ($payload['api'] ?? ''));

    $repository = lk3injectFirstActive(lk3read($repositoryPath));
    lk3write($repositoryPath, $repository);

    $appJs = lk3read($appJsPath);
    if (!str_contains($appJs, LK3_JS_MARKER)) {
        $appJs = rtrim($appJs) . PHP_EOL . PHP_EOL
            . '/* ' . LK3_JS_MARKER . ' */' . PHP_EOL
            . trim((string) ($payload['js'] ?? '')) . PHP_EOL;
        lk3write($appJsPath, $appJs);
    }

    $appCss = lk3read($appCssPath);
    if (!str_contains($appCss, LK3_JS_MARKER)) {
        $appCss = rtrim($appCss) . PHP_EOL . PHP_EOL
            . '/* ' . LK3_JS_MARKER . ' */' . PHP_EOL
            . trim((string) ($payload['css'] ?? '')) . PHP_EOL;
        lk3write($appCssPath, $appCss);
    }

    $schemaFragment = (string) ($payload['schema'] ?? '');
    $schema = lk3read($schemaPath);
    if (!str_contains($schema, 'LK3_PROJECT_SOURCES_SCHEMA_V180217')) {
        $schema = rtrim($schema) . PHP_EOL . PHP_EOL
            . trim($schemaFragment) . PHP_EOL;
        lk3write($schemaPath, $schema);
    }

    $sql = preg_replace('/^\s*--.*$/m', '', $schemaFragment) ?? $schemaFragment;
    $statements = preg_split('/;\s*(?=CREATE TABLE)/i', trim($sql)) ?: [];
    foreach ($statements as $statement) {
        $statement = trim($statement);
        if ($statement !== '') {
            $pdo->exec(rtrim($statement, "; \t\r\n"));
        }
    }

    lk3addColumn(
        $pdo,
        'conversion_goals',
        'site_id',
        'BIGINT UNSIGNED NULL',
        $addedColumns
    );
    lk3addColumn(
        $pdo,
        'conversion_goals',
        'scope_type',
        "VARCHAR(20) NOT NULL DEFAULT 'project'",
        $addedColumns
    );
    lk3addColumn(
        $pdo,
        'reports',
        'client_id',
        'BIGINT UNSIGNED NULL',
        $addedColumns
    );
    lk3addColumn(
        $pdo,
        'reports',
        'project_id',
        'BIGINT UNSIGNED NULL',
        $addedColumns
    );
    lk3addColumn(
        $pdo,
        'reports',
        'site_id',
        'BIGINT UNSIGNED NULL',
        $addedColumns
    );
    lk3addColumn(
        $pdo,
        'reports',
        'scope_type',
        "VARCHAR(20) NOT NULL DEFAULT 'project'",
        $addedColumns
    );

    if (lk3tableExists($pdo, 'conversion_goals')) {
        $pdo->exec(
            "UPDATE conversion_goals
             SET scope_type = 'project'
             WHERE scope_type IS NULL OR scope_type = ''"
        );
    }

    lk3lint($repositoryPath);
    lk3lint($servicePath);
    lk3lint($apiPath);

    if (function_exists('exec')) {
        $probeOutput = [];
        $probeCode = 0;
        $probe = "const value = null; value?.property; const fallback = value ?? 'ok';";
        exec('node -e ' . escapeshellarg($probe) . ' 2>&1', $probeOutput, $probeCode);
        if ($probeCode === 0) {
            $nodeOutput = [];
            $nodeCode = 0;
            exec('node --check ' . escapeshellarg($appJsPath) . ' 2>&1', $nodeOutput, $nodeCode);
            if ($nodeCode !== 0) {
                throw new RuntimeException(
                    'Ошибка JavaScript LK.3: ' . implode("\n", $nodeOutput)
                );
            }
        } else {
            lk3out('Проверка JavaScript через Node.js пропущена: серверная версия Node.js устарела.');
        }
    }

    if (substr_count(lk3read($repositoryPath), LK3_REPOSITORY_MARKER) !== 1) {
        throw new RuntimeException('ProjectRepository изменён некорректно.');
    }
    if (substr_count(lk3read($appJsPath), LK3_JS_MARKER) !== 1) {
        throw new RuntimeException('JavaScript LK.3 подключён некорректно.');
    }
    if (!lk3tableExists($pdo, 'project_source_links')
        || !lk3tableExists($pdo, 'report_site_links')) {
        throw new RuntimeException('Таблицы областей источников LK.3 не созданы.');
    }

    $projectCount = (int) $pdo->query(
        'SELECT COUNT(DISTINCT project_id) FROM project_sites'
    )->fetchColumn();
    $siteCount = (int) $pdo->query(
        'SELECT COUNT(*) FROM project_sites WHERE status <> "archived"'
    )->fetchColumn();

    lk3out('LK.3A: выбранный проект и источники разделов установлены.');
    lk3out('- старые разделы получают проект из глобального контекста;');
    lk3out('- системные процессы без сессии сохраняют исходный fallback;');
    lk3out('- проектов с сайтами: ' . $projectCount . ';');
    lk3out('- активных сайтов: ' . $siteCount . ';');
    lk3out('- добавлены области сайтов для отчётов и целей;');
    lk3out('- резервная копия: ' . $backupDirectory . ';');
} catch (Throwable $exception) {
    foreach ($manifest as $relative => $existed) {
        $target = $root . '/' . $relative;
        $backup = $backupDirectory . '/' . $relative;
        if ($existed && is_file($backup)) {
            @copy($backup, $target);
        } elseif (!$existed && is_file($target)) {
            @unlink($target);
        }
    }

    foreach (array_reverse($addedColumns) as [$table, $column]) {
        try {
            if (lk3columnExists($pdo, $table, $column)) {
                $pdo->exec(
                    'ALTER TABLE `' . $table . '` DROP COLUMN `' . $column . '`'
                );
            }
        } catch (Throwable) {
        }
    }
    foreach ($tableState as $table => $existed) {
        try {
            if (!$existed && lk3tableExists($pdo, $table)) {
                $pdo->exec('DROP TABLE `' . str_replace('`', '', $table) . '`');
            }
        } catch (Throwable) {
        }
    }

    fwrite(STDERR, 'ОШИБКА: ' . $exception->getMessage() . PHP_EOL);
    fwrite(STDERR, 'Файлы LK.3 восстановлены из резервной копии.' . PHP_EOL);
    exit(1);
}
